import{z as l,x as B,o as e,c as D,q as i,j as r,D as E,d as n,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CD 均匀性 CDU","description":"","frontmatter":{"title":"CD 均匀性 CDU","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cdu-uniformity.md","filePath":"litho/cdu-uniformity.md","lastUpdated":1791413859000}'),C={name:"litho/cdu-uniformity.md"};function p(A,a,d,h,m,c){const t=B("Mermaid");return e(),D("div",null,[a[2]||(a[2]=i('<h1 id="cd-均匀性-cdu" tabindex="-1">CD 均匀性 CDU <a class="header-anchor" href="#cd-均匀性-cdu" aria-label="Permalink to &quot;CD 均匀性 CDU&quot;">​</a></h1><div class="epigraph"><p>工艺窗口回答「这一点还活着吗」；CDU 回答「整场、整片、整批是不是同一点」。均匀性不合格时，窗口面积是一张不会兑现的地图。</p><footer>—— 据 Levinson 对 CD 控制与均匀性分解的产线讨论整理</footer></div><p><a href="/litho/fem-matrix">上一课</a>用一场一个 \\((E,z)\\) 把 Bossung 铺出来，并默认场代表同一工艺点。缺口是空间：镜头指纹、扫描狭缝、涂胶、PEB 热板、显影喷嘴会让名义同一剂量写出不同 CD。本课钉 CD 均匀性（CDU）。局部随机涨落（LCDU）已在<a href="/litho/euv-stochastics">随机效应</a>里，这里管的是可重复的空间指纹与场间差。怎么量每一条线，留给后课的 SEM / 散射测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FEM 给出的 EL 是「若全场都停在该 \\((E,z)\\)」的宽度。真实曝光场里，狭缝方向有照明与镜头指纹，扫描方向有速度与同步，晶圆半径方向有涂胶与热。于是同一产品场内 CD 已经扫过一小段 Bossung。规格若按全场 \\(3\\sigma\\) 切，有效窗口比矩阵中心那一场更瘦。</p><p><span class="marginnote">数字感受一下「窗口被吃掉」：假设规格允许全场宽度摆动 3 nm，而场内 CDU 指纹自己就占了 2 nm，留给离焦与剂量抖动的余量只剩 1 nm 量级——中心场 FEM 上看起来很宽的窗，落到边场可能所剩无几。</span></p><p>缺口因此是把 CD 的方差按空间尺度拆开：场内（intrafield）、场间（interfield）、片内径向、批次间。只报一个「CDU = 1 nm」而不声明尺度，等于把镜头和热板加在同一个榜上。</p><p><span class="marginnote">CDU（CD uniformity）就是「线宽均匀性」：同一片、同一层里，成千上万条本该一样宽的线，实际宽度摆动了多少纳米。它回答的不是「这条线准不准」，而是「所有线是不是都停在同一个工艺点上」。</span></p><h3 id="场内指纹不是随机" tabindex="-1">场内指纹不是随机 <a class="header-anchor" href="#场内指纹不是随机" aria-label="Permalink to &quot;场内指纹不是随机&quot;">​</a></h3><p>场内 CDU 往往可对镜头、照明光瞳、掩模 CD、扫描平均建模，属于可校正指纹。场间更多来自工件台、涂胶、PEB、显影。Levinson 把控制回路按贡献源分开：光学侧用剂量/照明/掩模，轨道侧用热与涂布。把轨道指纹拿去拧光瞳，会修错。</p><p><span class="marginnote">CDU 与 LCDU 不要混表。前者是场/片尺度的可重复图；后者是孔与线边的局部随机。加剂量主要压 LCDU，对 PEB 热板指纹几乎无效。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>采样：场内多点（含四角与中心、沿狭缝），片内多场（含边场），批次多片。统计写明：均值、\\(3\\sigma\\) 或百分位，以及是否已扣掉计量重复性。剂量补偿（dose mapper 一类公开能力）可以扳平场内平均 CD，但侧壁与随机尾部不会跟着一道变平。</p><p>监测分短环与产品：短环用稳定栈看设备指纹；产品 CDU 含薄膜与图形密度。两者不可互换验收。换胶或换底层后，旧补偿图要重测。</p><h3 id="与-fem-的接法" tabindex="-1">与 FEM 的接法 <a class="header-anchor" href="#与-fem-的接法" aria-label="Permalink to &quot;与 FEM 的接法&quot;">​</a></h3><p>FEM 应打在 CDU 已经受控的短环上，否则 Bossung 弯曲里混着空间指纹。反过来，产品补偿用 FEM 中心附近的剂量灵敏度：\\(\\partial\\mathrm{CD}/\\partial E\\) 把 CDU 纳米数换成需要的剂量校正。灵敏度来自窗口课，空间图来自本课。</p>',16)),(e(),r(s,null,{default:E(()=>[o(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEM%5B%22FEM%3A%20%E5%B1%80%E9%83%A8%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20S%5B%22%E5%89%82%E9%87%8F%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20IF%5B%22%E5%9C%BA%E5%86%85%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20CDU%5B%22CDU%20%E5%88%86%E8%A7%A3%22%5D%0A%20%20WF%5B%22%E5%9C%BA%E9%97%B4%20%2F%20%E5%BE%84%E5%90%91%22%5D%20--%3E%20CDU%0A%20%20S%20--%3E%20COR%5B%22%E5%89%82%E9%87%8F%20%2F%20%E8%BD%A8%E9%81%93%E8%A1%A5%E5%81%BF%22%5D%0A%20%20CDU%20--%3E%20COR%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>照明不均匀与镜头像差给出场内缓变 CD；扫描平均沿狭缝积分，又把时间噪声写成空间条纹。涂胶厚度改吸收与驻波（DUV）或有效剂量（EUV 薄胶）；PEB 热板的温度图直接改 CAR 的增益与扩散，CD 跟着走。显影喷嘴与旋转留下径向与弧形。这些机制在 FEM 的单个场设定里都看不见，只在片图上出现。</p><p>边场更差是常态：调平、浸没弯月面、涂胶边缘珠都在半径大处加码。用中心场的 FEM 窗去承诺边场产品，窗口会被边 CDU 吃掉。</p><p><span class="marginnote">掩模 CD 指纹会 1:1（经 MEEF）印进场内 CDU。校正扫描机补不平掩模，除非你愿意用剂量图去买光学侧的债。先分清掩模与镜头。</span></p><h3 id="控制环不要跨尺度" tabindex="-1">控制环不要跨尺度 <a class="header-anchor" href="#控制环不要跨尺度" aria-label="Permalink to &quot;控制环不要跨尺度&quot;">​</a></h3><p>场内光学指纹用扫描仪校正；轨道指纹用热板与涂布；批次漂移用 APC 调名义剂量。三环共用一个「加剂量」旋钮时，短期会把均值扳回规格，长期把侧壁和随机推到窗外。CDU 合格必须声明是哪一环的残差。</p><p>上一张图画的是 CDU 与 FEM、补偿的接法；这里补一张分解图，回答另一个问题：一个笼统的 CDU 纳米数，到底由哪些来源构成、各归哪个旋钮修。</p>',7)),(e(),r(s,null,{default:E(()=>[o(t,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%95%B4%E6%89%B9%20CD%20%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20IF%5B%22%E5%9C%BA%E5%86%85%EF%BC%9A%E9%95%9C%E5%A4%B4%20%2F%20%E7%85%A7%E6%98%8E%20%2F%20%E6%8E%A9%E6%A8%A1%20CD%22%5D%0A%20%20T%20--%3E%20EF%5B%22%E5%9C%BA%E9%97%B4%EF%BC%9A%E5%B7%A5%E4%BB%B6%E5%8F%B0%20%2F%20%E6%B6%82%E8%83%B6%20%2F%20PEB%20%2F%20%E6%98%BE%E5%BD%B1%22%5D%0A%20%20T%20--%3E%20RAD%5B%22%E7%89%87%E5%86%85%E5%BE%84%E5%90%91%EF%BC%9A%E8%BE%B9%E5%9C%BA%20%2F%20%E8%B0%83%E5%B9%B3%20%2F%20%E8%BE%B9%E7%BC%98%E7%8F%A0%22%5D%0A%20%20T%20--%3E%20LOT%5B%22%E6%89%B9%E6%AC%A1%E9%97%B4%EF%BC%9A%E7%BC%93%E6%85%A2%E6%BC%82%E7%A7%BB%22%5D%0A%20%20IF%20--%3E%20FIX1%5B%22%E6%89%AB%E6%8F%8F%E4%BB%AA%E4%BE%A7%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20EF%20--%3E%20FIX2%5B%22%E7%83%AD%E6%9D%BF%E4%B8%8E%E6%B6%82%E5%B8%83%E4%BE%A7%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20LOT%20--%3E%20FIX3%5B%22APC%20%E8%B0%83%E5%90%8D%E4%B9%89%E5%89%82%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">常见误区：CDU 不达标就无脑加剂量或拧光瞳。指纹可能来自 PEB 热板的温度图，光刻侧旋钮拧到底也没用，反而把侧壁和随机尾部推坏——先按空间尺度分解，再找对应的那一环去修。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某机型的场内 CDU 公开规格写成所有层的宇宙常数，也不把刻蚀后 CDU 提前算进光刻——刻蚀偏置是后课。套刻指纹与 CD 指纹会耦合（离焦改 CD 也改有效套准），但本课的对象仍是宽度，不是位移。</p><p>后课默认：窗口面积要扣掉 CDU 指纹才能兑现；说到均匀性必须写尺度。计量偏置如何系统平移整张图，在 CD-SEM / OCD 课展开。</p><p><span class="marginnote">报 CDU 必须写：显影后还是刻蚀后、何种图形、场内还是片内、是否含边场。缺一项，纳米数不可比。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CDU 把 FEM 的「一点」展开成场内 / 场间 / 片内的空间图。</li><li>场内多属光学与掩模指纹，场间多属轨道；修错环等于假均匀。</li><li>LCDU 是随机局部量，与 CDU 分表。</li><li>边场和密度依赖会吃掉中心场的窗口。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack 对工艺控制与剂量灵敏度的讨论。</li></ul>',7))])}const _=l(C,[["render",p]]);export{u as __pageData,_ as default};
